mapper.select:
select asset_code,invest_type,facevalue,invest_variety,trade_type,is_under_trade,prod_id,CHL_CPCT_ID CHL_ID,dealdate cdate, ccy, sum( case when CUR_ASSET_TYPE in ('01','03','05','06') then AMT else 0-AMT end ) dealamt ,sum( case when CUR_ASSET_TYPE in ('01','03','05','06') then NUM else 0-NUM end ) dealqty from chb_invest_trade where dealdate=#{cdate,jdbcType=DATE}
and prod_id in
#{prodid}
and asset_code in
#{assetcode}
and STATUS!='D' and CUR_ASSET_TYPE in ('01','03','05','06') group by asset_code,invest_type,facevalue,invest_variety, trade_type,is_under_trade,prod_id,CHL_CPCT_ID,dealdate,ccy

select asset_code,invest_type,facevalue,invest_variety, trade_type,cur_asset_type, is_under_trade,prod_id,CHL_CPCT_ID CHL_ID,dealdate cdate, ccy, sum( case when CUR_ASSET_TYPE in ('01','03','05','06') then AMT else 0-AMT end ) dealamt ,sum( case when CUR_ASSET_TYPE in ('01','03','05','06') then NUM when CUR_ASSET_TYPE in ('11') then 0-AMT else 0-NUM end ) dealqty from chb_invest_trade where dealdate=#{cdate,jdbcType=DATE}
and prod_id in
#{prodid}
and asset_code in
#{assetcode}
and STATUS!='D' and (CUR_ASSET_TYPE in ('02','04','07','08') or (CUR_ASSET_TYPE='11' and dealtype='24')) group by asset_code,invest_type,facevalue,invest_variety, trade_type,cur_asset_type,ccy ,is_under_trade,prod_id,CHL_CPCT_ID,dealdate

mapper.insert:
insert into CHB_ASSET_POSITION SELECT f_guid(), PROD_ID, ASSET_CODE, INVEST_TYPE, CHL_ID, 0, 0, ACCUAMT, ACCUQTY, CDATE+1, ORG_CODE, DEPT_CODE, CREATE_USER, NOW(), UPDATE_USER, NOW(), TRADE_TYPE, IS_UNDER_TRADE, INVEST_VARIETY, CCY FROM CHB_ASSET_POSITION where CDATE=#{cdate,jdbcType=DATE} and ACCUAMT<>0 and ACCUQTY<>0
and ASSET_CODE !='REMAININGCASH'
and prod_id in
#{prodid}
and asset_code in
#{assetcode}

mapper.select:
select

from CHB_ASSET_POSITION
where 1=1

    and asset_code=#{assetCode,jdbcType=VARCHAR}


    and cdate=#{cdate,jdbcType=DATE}


    and invest_variety=#{investVariety,jdbcType=VARCHAR}


    and invest_type=#{investType,jdbcType=VARCHAR}


    and prod_id=#{prodId,jdbcType=VARCHAR}


    and chl_id=#{chlId,jdbcType=VARCHAR}


    and is_under_trade=#{isundertrade,jdbcType=VARCHAR}


    and trade_type=#{tradeType,jdbcType=VARCHAR}


    and ccy=#{ccy,jdbcType=VARCHAR}

