where CDATE=#{cdate,jdbcType=DATE}
and ASSET_CODE='REMAININGCASH'

    and PROD_ID in

        #{prodid}

SELECT
case
when min(dealdate) is  null
then #{cdate,jdbcType=DATE}
when min(dealdate) is not null and min(dealdate)>#{cdate,jdbcType=DATE}
then #{cdate,jdbcType=DATE}
when min(dealdate) is not null and min(dealdate)<=#{cdate,jdbcType=DATE}
then  min(dealdate) end  SETTDATEDATE
FROM chb_invest_trade
WHERE
DATE_FORMAT(update_time,'%Y-%m-%d')=DATE_FORMAT(#{cdate,jdbcType=DATE},'%Y-%m-%d')

    and prod_id in

        #{prodid}



    and asset_code in

        #{assetcode}

SELECT ifnull(min(SETTDATEDATE),#{cdate,jdbcType=DATE}) FROM ( SELECT min(BALANCE.BALANCE_DATE) SETTDATEDATE FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_MARKET_ID = replace(BALANCE.BOOKSET_ID,'F16_','') LEFT JOIN FIN_PRODUCT_ADD PRODADD /*产品附属信息表*/ ON replace(BALANCE.BOOKSET_ID,'F16_','')=PRODADD.PORTFOLIO_ID WHERE 1 =1 AND DATE_FORMAT(ifnull(BALANCE.UPDATE_TIME,BALANCE.CREATE_TIME),'%Y-%m-%d') = DATE_FORMAT(#{cdate,jdbcType=DATE},'%Y-%m-%d') /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' and BOOKSET.ACCT_SUBJECT_TYPE = 'F18'/*取账套表的主体核算类型为F18投资组合*/ and prodadd.PROFIT_FLAG = '03'/*只取非保本理财产品 */
#{prodid,jdbcType=VARCHAR}
union all SELECT min(BALANCE.BALANCE_DATE) SETTDATEDATE FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD /*产品附属信息表*/ ON BALANCE.BOOKSET_ID=PRODADD.FINPROD_ID WHERE 1 =1 AND DATE_FORMAT(ifnull(BALANCE.UPDATE_TIME,BALANCE.CREATE_TIME),'%Y-%m-%d') = DATE_FORMAT(#{cdate,jdbcType=DATE},'%Y-%m-%d') /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' AND BOOKSET.ACCT_SUBJECT_TYPE = 'F16'/*取账套表的主体核算类型为F16净值型产品货币性产品*/ and prodadd.PROFIT_FLAG = '03'/*只取非保本理财产品 */
#{prodid,jdbcType=VARCHAR}
)

SELECT NULL POSUUID,/*头寸ID:自动生成*/ PRODID PROD_ID,/*产品代码*/ 'REMAININGCASH' ASSET_CODE,/*资产代码*/ NULL INVEST_TYPE,/*投资类型*/ NULL CHL_ID,/*通道代码*/ 0 DEALAMT,/*交易金额*/ 0 DEALQTY,/*交易份额*/ SUM(ACCUAMT) ACCUAMT,/*剩余金额*/ SUM(ACCUQTY) ACCUQTY,/*剩余本金*/ CDATE CDATE,/*生成日*/ NULL ORG_CODE,/*机构代码*/ NULL DEPT_CODE,/*部门代码*/ NULL CREATE_USER,/*创建人*/ NULL CREATE_TIME,/*创建时间*/ NULL UPDATE_USER,/*更新人*/ NULL UPDATE_TIME,/*更新时间*/ '01' TRADE_TYPE, /*交易类型:关联资产要素信息表，判断ASSET_TYPE字段的值，若为12,15,16,19则该字段存05，否则存01*/ '02' IS_UNDER_TRADE,/*是否底层交易流水:02 否*/ NULL INVEST_VARIETY,/*投资品种 01债券 02ABS*/ CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM( SELECT PROD.FINPROD_MARKET_ID PRODID,/*产品代码*/ BALANCE.O_AMT ACCUAMT,/*剩余金额*/ BALANCE.O_AMT ACCUQTY,/*剩余本金*/ BALANCE.BALANCE_DATE CDATE,/*生成日*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_MARKET_ID = BALANCE.BOOKSET_ID WHERE 1 =1 AND BALANCE.BALANCE_DATE = #{cdate,jdbcType=DATE} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' and BOOKSET.ACCT_SUBJECT_TYPE = 'F18'/*取账套表的主体核算类型为F18投资组合*/ and exists (select 1 from FIN_PRODUCT_ADD PRODADD where BALANCE.BOOKSET_ID = PRODADD.PORTFOLIO_ID and prodadd.PROFIT_FLAG = '03')/*只取非保本理财产品 */ /*AND BALANCE.SUBJECT_NO IN ( '10020101','10020102','10020103','10020104','10020105','10020106','10020107','10020108','10020109','10020110','10020111','10020112', '10210101','10310101','10310102' )*//*现金科目*/
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
UNION ALL SELECT PROD.FINPROD_MARKET_ID PRODID,/*产品代码*/ BALANCE.O_AMT ACCUAMT,/*剩余金额*/ BALANCE.O_AMT ACCUQTY,/*剩余本金*/ BALANCE.BALANCE_DATE CDATE,/*生成日*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_ID = BALANCE.BOOKSET_ID WHERE 1 =1 AND BALANCE.BALANCE_DATE = #{cdate,jdbcType=DATE} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' AND BOOKSET.ACCT_SUBJECT_TYPE = 'F16'/*取账套表的主体核算类型为F16净值型产品货币性产品*/ and exists (select 1 from FIN_PRODUCT_ADD PRODADD where BALANCE.BOOKSET_ID = PRODADD.FINPROD_ID and prodadd.PROFIT_FLAG = '03')/*只取非保本理财产品 */ /*AND BALANCE.SUBJECT_NO IN ( '10020101','10020102','10020103','10020104','10020105','10020106','10020107','10020108','10020109','10020110','10020111','10020112', '10210101','10310101','10310102' )*/ /*现金科目*/
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
UNION ALL SELECT VAL.PORTFOLIO_ID PRODID,/*产品代码*/ val.amount ACCUAMT,/*剩余金额*/ val.amount ACCUQTY,/*剩余本金*/ VAL.CDATE CDATE,/*生成日*/ VAL.CCY CCY /*币种*/ from ptl_cash_position VAL WHERE 1 =1 AND VAL.CDATE = #{cdate,jdbcType=DATE} and exists (select 1 from fin_product_add d where d.portfolio_id = val.portfolio_id and d.profit_flag = '03')/*只取非保本理财产品*/ and val.HODING_TYPE = '03' /*只取实际*/ and VAL.CHL_FINPROD_ID is not null ---只取通道id不为空的数据
#{prodid,jdbcType=VARCHAR}
) GROUP BY PRODID,CDATE,CCY

SELECT NULL POSUUID,/*头寸ID:自动生成*/ PRODINFO.PROD_ID PROD_ID,/*产品代码*/ 'REMAININGCASH' ASSET_CODE,/*资产代码*/ NULL INVEST_TYPE,/*投资类型*/ NULL CHL_ID,/*通道代码*/ 0 DEALAMT,/*交易金额*/ 0 DEALQTY,/*交易份额*/ SUM(BALANCE.O_AMT) ACCUAMT,/*剩余金额*/ SUM(BALANCE.O_AMT) ACCUQTY,/*剩余本金*/ BALANCE.BALANCE_DATE CDATE,/*生成日*/ NULL ORG_CODE,/*机构代码*/ NULL DEPT_CODE,/*部门代码*/ NULL CREATE_USER,/*创建人*/ NULL CREATE_TIME,/*创建时间*/ NULL UPDATE_USER,/*更新人*/ NULL UPDATE_TIME,/*更新时间*/ '01' TRADE_TYPE, /*交易类型:关联资产要素信息表，判断ASSET_TYPE字段的值，若为12,15,16,19则该字段存05，否则存01*/ '02' IS_UNDER_TRADE,/*是否底层交易流水:02 否*/ NULL INVEST_VARIETY,/*投资品种 01债券 02ABS*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN CHB_PRD_BASEINFO PRODINFO /*产品要素信息*/ on prodinfo.PROD_ID = replace(balance.BOOKSET_ID,'F16_','') WHERE 1 =1 AND DATE_FORMAT(BALANCE.BALANCE_DATE,'%Y-%m-%d') = DATE_FORMAT(#{cdate,jdbcType=DATE},'%Y-%m-%d') and prodinfo.PROFIT_TYPE = '03'/*只取非保本理财产品 */ /*AND BALANCE.SUBJECT_NO IN ( '10020101','10020102','10020103','10020104','10020105','10020106','10020107','10020108','10020109','10020110','10020111','10020112', '10210101','10310101','10310102')*//*现金科目*/
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
GROUP BY PRODINFO.prod_id,BALANCE.BALANCE_DATE,BALANCE.O_CCY
